  assert.equal(branchOf({ field: 'x', operator: 'gte', value: 1 }, { x: true }), 'passed');
  assert.equal(branchOf({ field: 'x', operator: 'lte', value: 0 }, { x: false }), 'passed');
  assert.equal(branchOf({ field: 'x', operator: 'gte', value: null }, { x: null }), 'passed');
